            "question_image": "https://drive.google.com/file/d/1IVvRwiRggz-gity6eq_YExYu4rl8GEYE/preview",
            "local_question_image": "assets/quiz-images/img_1IVvRwiRggz-gity6eq_YExYu4rl8GEYE.jpg",
            "times_presented": 0,
            "options": [
                {
                    "label": "A",
                    "text": "41.5 mph",
                    "is_correct": true
                },
                {
                    "label": "B",
                    "text": "45.0 mph",
                    "is_correct": false
                },
                {
                    "label": "C",
                    "text": "48.2 mph",
                    "is_correct": false
                },
                {
                    "label": "D",
                    "text": "50.0 mph",
                    "is_correct": false
                }
            ],
            "solution": {
                "steps": [
                    {
                        "title": "Identify Formula",
                        "content": "Space Mean Speed is the harmonic mean of speeds: $u_s = \\frac{n}{\\sum \\frac{1}{u_i}}$."
                    },
                    {
                        "title": "Perform the Calculation",
                        "content": "$u_s = \\frac{3}{\\frac{1}{30} + \\frac{1}{45} + \\frac{1}{60}} = \\frac{3}{0.0333 + 0.0222 + 0.0167} = \\frac{3}{0.0722} \\approx 41.54$ mph."
                    }
                ],
                "final_answer": "A",
                "solution_image": "",
                "video_explanation": ""
            },
