                    {
                        "title": "Calculate Actual Pressure (q_act)",
                        "content": "$q_{act} = Q / B = 150 / 1.2 = 125 \\, kPa$."
                    },
                    {
                        "title": "Determine Factor of Safety (FS)",
                        "content": "$FS = q_u / q_{act} = 361 / 125 = 2.888 \\approx 2.9$."
                    }
